 13→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 14→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
